/bin/bash -lc "cat > src/util/ordersApi.mjs <<'EOF'
// Normalizes the backend's order-list response into a stable shape.
// The backend list response defines:
//   orders      - the list of orders on this page
//   totalPages  - number of pages
//   recordsTotal - total number of records
//   recordsCount - number of records on this page (falls back to the list length)

function toNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

export function normalizeOrderList(response) {
  const source = response && typeof response === \"object\" ? response : {};

  const orders = Array.isArray(source.orders) ? source.orders : [];
  const pages = toNumber(source.totalPages);
  const total = toNumber(source.recordsTotal);

  const rawOnThisPage = Number(source.recordsCount);
  const onThisPage = Number.isFinite(rawOnThisPage) ? rawOnThisPage : orders.length;

  return { orders, pages, total, onThisPage };
}
EOF
